async function hydrateCompany(ticker) { try { const data = await getJson(`/data/company?symbol=${encodeURIComponent(ticker)}`); const profile = data.profile || {}; const quote = data.quote || {}; const ratios = data.ratios || {}; const metrics = data.metrics || {}; const set = (id, value) => { const element = $(`#${id}`); if (element) element.textContent = value; }; const ratio = (value, digits = 2) => Number.isFinite(Number(value)) ? Number(value).toFixed(digits) : '—'; const pct = (value, digits = 1) => Number.isFinite(Number(value)) ? `${(Number(value) * 100).toFixed(digits)}%` : '—'; set('company-title', profile.companyName || ticker); set('company-subtitle', `${ticker} · ${profile.exchangeShortName || profile.exchange || 'US Equity'}`); set('company-description', profile.description || 'Company profile is unavailable from the current provider.'); set('company-cap', usd(profile.mktCap || quote.marketCap)); set('company-price', quote.price ? `$${Number(quote.price).toFixed(2)}` : '—'); const change = quote.changesPercentage; const changeElement = $('#company-change'); if (changeElement) { changeElement.textContent = Number.isFinite(Number(change)) ? `${percent(change)} today` : 'Latest available quote'; changeElement.className = Number(change) >= 0 ? 'positive' : 'down'; } set('company-range', quote.dayHigh && quote.dayLow ? `$${Number(quote.dayLow).toFixed(2)} / $${Number(quote.dayHigh).toFixed(2)}` : '—'); set('company-pe', ratios.peRatioTTM ? `${ratio(ratios.peRatioTTM, 1)}x` : '—'); set('company-book', metrics.bookValuePerShareTTM ? `$${ratio(metrics.bookValuePerShareTTM, 2)}` : '—'); set('company-dividend', pct(ratios.dividendYieldTTM, 2)); set('company-roe', pct(ratios.returnOnEquityTTM)); set('company-current', ratio(ratios.currentRatioTTM)); set('company-debt', ratio(ratios.debtToEquityRatioTTM)); set('company-pb', ratios.priceToBookRatioTTM ? `${ratio(ratios.priceToBookRatioTTM, 1)}x` : '—'); set('company-volume', whole(quote.volume)); set('company-sector', profile.sector || '—'); const site = $('#company-site'); if (site) site.innerHTML = profile.website ? `<a href="${escapeHtml(profile.website)}" target="_blank" rel="noreferrer">Website ↗</a>` : '—'; const points = $('#company-keypoints'); const income = data.income || []; if (points) { const latest = income[0] || {}; const previous = income[1] || {}; const growth = latest.revenue && previous.revenue ? ((latest.revenue - previous.revenue) / Math.abs(previous.revenue)) * 100 : null; points.innerHTML = `<p class="about-label">KEY POINTS</p><ul>${Number.isFinite(growth) ? `<li>Revenue changed ${percent(growth)} in the latest reported year.</li>` : ''}${latest.netIncome && latest.revenue ? `<li>Latest reported net margin: ${((latest.netIncome / latest.revenue) * 100).toFixed(1)}%.</li>` : ''}</ul>`; } const financials = $('#financials'); if (financials) financials.innerHTML = financialTable('Income statement', data.income || [], [['Revenue','revenue'],['Gross profit','grossProfit'],['Operating income','operatingIncome'],['Net income','netIncome'],['EPS','eps']]) + financialTable('Balance sheet', data.balance || [], [['Cash & equivalents','cashAndCashEquivalents'],['Total assets','totalAssets'],['Total debt','totalDebt'],['Total liabilities','totalLiabilities'],['Total equity','totalStockholdersEquity']]) + financialTable('Cash flow', data.cashflow || [], [['Operating cash flow','operatingCashFlow'],['Capital expenditure','capitalExpenditure'],['Free cash flow','freeCashFlow'],['Net income','netIncome']]); const ratiosElement = $('#company-ratios'); if (ratiosElement) ratiosElement.innerHTML = ratioCard('P/E', ratios.peRatioTTM ? `${ratio(ratios.peRatioTTM, 1)}x` : '—') + ratioCard('Price to book', ratios.priceToBookRatioTTM ? `${ratio(ratios.priceToBookRatioTTM, 1)}x` : '—') + ratioCard('Return on equity', pct(ratios.returnOnEquityTTM)) + ratioCard('Current ratio', ratio(ratios.currentRatioTTM)) + ratioCard('Debt to equity', ratio(ratios.debtToEquityRatioTTM)) + ratioCard('Dividend yield', pct(ratios.dividendYieldTTM, 2)); getJson(`/data/chart?symbol=${encodeURIComponent(ticker)}&points=${companyChartOptions.points}`).then(chart => { const holder = $('#company-chart'); if (holder) holder.innerHTML = drawCompanyChart(chart.values || []); }).catch(() => { const holder = $('#company-chart'); if (holder) holder.innerHTML = '<p class="data-empty">Price history is temporarily unavailable.</p>'; }); } catch { const description = $('#company-description'); if (description) description.textContent = 'Live company data is temporarily unavailable.'; } }
